export class RecursiveScaffolding {
  constructor(modules) {
    this.modules = modules;
  }

  evaluateAndIntegrate() {
    const moduleOutputs = this.modules.map(module => module.generateOutput());
    const weightedOutputs = moduleOutputs.map(output => {
      return {
        output: output.content,
        weight: output.confidence
      };
    });

    const integratedOutput = weightedOutputs.reduce((acc, curr) => {
      acc.content += curr.output * curr.weight;
      acc.totalWeight += curr.weight;
      return acc;
    }, { content: 0, totalWeight: 0 });

    return integratedOutput.content / integratedOutput.totalWeight;
  }
}